SELECT CONCAT(firstName, ' ', lastName) AS full_name FROM employees WHERE reportsTo = ( SELECT employeeNumber FROM employees WHERE CONCAT(firstName, ' ', lastName) = 'Mary Patterson' );	classicmodels
SELECT p.customerNumber, p.paymentDate, p.amount FROM payments p WHERE p.amount > 2 * ( SELECT AVG(p2.amount) FROM payments p2 WHERE MONTH(p2.paymentDate) = MONTH(p.paymentDate) AND YEAR(p2.paymentDate) = YEAR(p.paymentDate) ) ORDER BY p.paymentDate;	classicmodels
SELECT productName, productLine, quantityInStock, ROUND((quantityInstock / ( SELECT SUM(p2.quantityInStock) FROM products p2 WHERE p2.productLine = p1.productLine )) * 100, 2) AS stock_percentage FROM products p1 ORDER BY productLine, stock_percentage DESC;	classicmodels
SELECT od.orderNumber, od.productCode, (od.priceEach * od.quantityOrdered) AS product_value, ROUND((od.priceEach * od.quantityOrdered) / (SELECT SUM(od2.priceEach * od2.quantityOrdered) FROM orderdetails od2 WHERE od2.orderNumber = od.orderNumber) * 100, 2) AS product_percentage FROM orderdetails od WHERE (od.priceEach * od.quantityOrdered) > (SELECT SUM(od2.priceEach * od2.quantityOrdered) * 0.5 FROM orderdetails od2 WHERE od2.orderNumber = od.orderNumber) AND od.orderNumber IN ( SELECT orderNumber FROM orderdetails GROUP BY orderNumber HAVING COUNT(DISTINCT productCode) > 2 ) ORDER BY od.orderNumber, product_percentage DESC;	classicmodels
SELECT * FROM employees WHERE reportsTo IS NULL;	classicmodels
SELECT employeeNumber, firstName, lastName, jobTitle FROM employees WHERE reportsTo = ( SELECT employeeNumber FROM employees WHERE LOWER(CONCAT(firstname, ' ', lastname)) = 'William Patterson' );	classicmodels
SELECT DISTINCT p.productName FROM products p JOIN orderdetails od ON p.productCode = od.productCode JOIN orders o ON od.orderNumber = o.orderNumber JOIN customers c ON o.customerNumber = c.customerNumber WHERE c.customerName = 'Herkku Gifts';	classicmodels
SELECT SUM(od.priceEach * od.quantityOrdered * 0.05) AS comission, CONCAT(e.lastName, ' ', e.firstName) AS sales_representative FROM orderdetails od JOIN orders o ON od.orderNumber = o.orderNumber JOIN customers c ON o.customerNumber = c.customerNumber JOIN employees e ON c.salesRepEmployeeNumber = e.employeeNumber GROUP BY e.employeeNumber, e.lastName, e.firstName ORDER BY e.lastName, e.firstName;	classicmodels
SELECT DATEDIFF(MAX(orderDate), MIN(orderDate)) AS days_difference FROM orders;	classicmodels
SELECT AVG(DATEDIFF(o.shippedDate, o.orderDate)) AS difference_in_days, o.customerNumber, c.customerName FROM orders o JOIN customers c ON o.customerNumber = c.customerNumber GROUP BY o.customerNumber, c.customerName ORDER BY difference_in_days DESC;	classicmodels
SELECT SUM(od.priceEach * od.quantityOrdered) AS value_of_order FROM orderdetails od JOIN orders o ON od.orderNumber = o.orderNumber WHERE o.shippedDate BETWEEN '2004-08-01' AND '2004-08-31';	classicmodels
SELECT o.customerNumber, c.customerName, SUM(od.priceEach * od.quantityOrdered) AS total_value_ordered, SUM(p.amount) AS total_amount_paid, SUM(od.priceEach * od.quantityOrdered) - SUM(p.amount) AS difference FROM orders o JOIN orderdetails od ON o.orderNumber = od.orderNumber JOIN customers c ON o.customerNumber = c.customerNumber LEFT JOIN payments p ON o.customerNumber = p.customerNumber WHERE o.orderDate BETWEEN '2004-01-01' AND '2004-12-31' AND p.paymentDate BETWEEN '2004-01-01' AND '2004-12-31' GROUP BY o.customerNumber, c.customerName ORDER BY difference DESC;	classicmodels
SELECT e.employeeNumber, CONCAT(e.firstName, ' ', e.lastName) AS full_name FROM employees e WHERE e.reportsTo IN ( SELECT employeeNumber FROM employees WHERE reportsTo = ( SELECT employeeNumber FROM employees WHERE CONCAT(firstName, ' ', lastName) = 'Diane Murphy' ) );	classicmodels
SELECT productCode, productName, (quantityInStock * buyPrice) AS product_value, ((quantityInStock * buyPrice) / (SELECT SUM(quantityInStock * buyPrice) FROM products)) * 100 AS percentage_value FROM products ORDER BY percentage_value DESC;	classicmodels
SELECT SUM(amount) AS total_July_2004_payments FROM payments WHERE paymentDate BETWEEN '2004-07-01' AND '2004-07-31';	classicmodels
SELECT COALESCE(p.month, o.month) AS month, COALESCE(p.year, o.year) AS year, COALESCE(total_payments, 0) AS total_payments, COALESCE(total_order_value, 0) AS total_order_value, COALESCE(total_payments, 0) / COALESCE(total_order_value, 1) AS payment_to_order_ratio FROM ( SELECT MONTHNAME(paymentDate) AS month, YEAR(paymentDate) AS year, SUM(amount) AS total_payments FROM payments WHERE YEAR(paymentDate) = 2004 GROUP BY year, month ) p LEFT JOIN ( SELECT MONTHNAME(o.orderDate) AS month, YEAR(o.orderDate) AS year, SUM(od.priceEach * od.quantityOrdered) AS total_order_value FROM orders o JOIN orderdetails od ON o.orderNumber = od.orderNumber WHERE YEAR(o.orderDate) = 2004 GROUP BY year, month ) o ON p.month = o.month AND p.year = o.year UNION SELECT COALESCE(p.month, o.month) AS month, COALESCE(p.year, o.year) AS year, COALESCE(total_payments, 0) AS total_payments, COALESCE(total_order_value, 0) AS total_order_value, COALESCE(total_payments, 0) / COALESCE(total_order_value, 1) AS payment_to_order_ratio FROM ( SELECT MONTHNAME(paymentDate) AS month, YEAR(paymentDate) AS year, SUM(amount) AS total_payments FROM payments WHERE YEAR(paymentDate) = 2004 GROUP BY year, month ) p RIGHT JOIN ( SELECT MONTHNAME(o.orderDate) AS month, YEAR(o.orderDate) AS year, SUM(od.priceEach * od.quantityOrdered) AS total_order_value FROM orders o JOIN orderdetails od ON o.orderNumber = od.orderNumber WHERE YEAR(o.orderDate) = 2004 GROUP BY year, month ) o ON p.month = o.month AND p.year = o.year ORDER BY year, month;	classicmodels
SELECT MONTHNAME(paymentDate) AS month, MONTH(paymentDate) AS month_number, SUM(CASE WHEN YEAR(paymentDate) = 2004 THEN amount ELSE 0 END) AS total_2004, SUM(CASE WHEN YEAR(paymentDate) = 2003 THEN amount ELSE 0 END) AS total_2003, SUM(CASE WHEN YEAR(paymentDate) = 2004 THEN amount ELSE 0 END) - SUM(CASE WHEN YEAR(paymentDate) = 2003 THEN amount ELSE 0 END) AS difference FROM payments WHERE YEAR(paymentDate) IN (2003, 2004) GROUP BY month, month_number ORDER BY month_number;	classicmodels
SELECT quantityOrdered FROM orderdetails WHERE productCode = ( SELECT productCode FROM products WHERE productName = '1969 Dodge Charger') AND orderNumber = 10405;	classicmodels
SELECT c.customerName, SUM(od.priceEach * od.quantityOrdered) AS customer_revenue, ROUND((SUM(od.priceEach * od.quantityOrdered) / (SELECT SUM(od.priceEach * od.quantityOrdered) FROM orders o JOIN orderdetails od ON od.orderNumber = o.orderNumber)) * 100, 2) AS revenue_percentage FROM orderdetails od JOIN orders o ON od.orderNumber = o.orderNumber JOIN customers c ON o.customerNumber = c.customerNumber GROUP BY c.customerName ORDER BY c.customerName;	classicmodels
SELECT c.customerName, ROUND(SUM((od.priceEach - p.buyPrice) * od.quantityOrdered), 2) AS customer_profit, ROUND((SUM((od.priceEach - p.buyPrice) * od.quantityOrdered) / (SELECT SUM((od.priceEach - p.buyPrice) * od.quantityOrdered) FROM orderdetails od JOIN products p ON od.productCode = p.productCode)) * 100, 2) AS profit_percentage FROM orderdetails od JOIN orders o ON od.orderNumber = o.orderNumber JOIN products p ON od.productCode = p.productCode JOIN customers c ON o.customerNumber = c.customerNumber GROUP BY c.customerName ORDER BY customer_profit DESC;	classicmodels
SELECT c.salesRepEmployeeNumber, ROUND(SUM(od.priceEach * od.quantityOrdered), 2) AS salesrep_revenue FROM orderdetails od JOIN orders o ON od.orderNumber = o.orderNumber JOIN customers c ON o.customerNumber = c.customerNumber WHERE c.salesRepEmployeeNumber IS NOT NULL GROUP BY c.salesRepEmployeeNumber ORDER BY salesrep_revenue DESC;	classicmodels
SELECT c.salesRepEmployeeNumber, ROUND(SUM((od.priceEach - p.buyPrice) * od.quantityOrdered), 2) AS salesrep_profit FROM orderdetails od JOIN orders o ON od.orderNumber = o.orderNumber JOIN products p ON od.productCode = p.productCode JOIN customers c ON o.customerNumber = c.customerNumber WHERE c.salesRepEmployeeNumber IS NOT NULL GROUP BY c.salesRepEmployeeNumber ORDER BY salesrep_profit DESC;	classicmodels
SELECT p.productName, ROUND(SUM(od.priceEach * od.quantityOrdered), 2) AS product_revenue FROM orderdetails od JOIN orders o ON od.orderNumber = o.orderNumber JOIN products p ON od.productCode = p.productCode GROUP BY p.productName ORDER BY p.productName;	classicmodels
SELECT p.productLine, ROUND(SUM((od.priceEach - p.buyPRice) * od.quantityOrdered), 2) AS productline_profit FROM orderdetails od JOIN orders o ON od.orderNumber = o.orderNumber JOIN products p ON od.productCode = p.productCode GROUP BY p.productLine ORDER BY productline_profit DESC;	classicmodels
SELECT p.productName, p.productCode, SUM(CASE WHEN YEAR(o.orderDate) = 2004 THEN od.priceEach * od.quantityOrdered ELSE 0 END) AS sales_2004, SUM(CASE WHEN YEAR(o.orderDate) = 2003 THEN od.priceEach * od.quantityOrdered ELSE 0 END) AS sales_2003, (SUM(CASE WHEN YEAR(o.orderDate) = 2004 THEN od.priceEach * od.quantityOrdered ELSE 0 END) / NULLIF(SUM(CASE WHEN YEAR(o.orderDate) = 2003 THEN od.priceEach * od.quantityOrdered ELSE 0 END), 0) ) AS sales_ratio FROM products p JOIN orderdetails od ON p.productCode = od.productCode JOIN orders o ON od.orderNumber = o.orderNumber GROUP BY p.productCode ORDER BY sales_ratio DESC;	classicmodels
SELECT c.customerNumber, c.customerName, SUM(CASE WHEN YEAR(p.paymentDate) = 2004 THEN p.amount ELSE 0 END) AS payments_2004, SUM(CASE WHEN YEAR(p.paymentDate) = 2003 THEN p.amount ELSE 0 END) AS payments_2003, (SUM(CASE WHEN YEAR(p.paymentDate) = 2004 THEN p.amount ELSE 0 END) / NULLIF(SUM(CASE WHEN YEAR(p.paymentDate) = 2003 THEN p.amount ELSE 0 END), 0) ) AS payments_ratio FROM payments p JOIN customers c ON p.customerNumber = c.customerNumber GROUP BY c.customerNumber, c.customerName ORDER BY payments_ratio DESC;	classicmodels
SELECT DISTINCT p.productName FROM products p JOIN orderdetails od ON p.productCode = od.productCode JOIN orders o ON od.orderNumber = o.orderNumber WHERE YEAR(o.orderDate) = 2003 AND p.productCode NOT IN ( SELECT DISTINCT p2.productCode FROM products p2 JOIN orderdetails od2 ON p2.productCode = od2.productCode JOIN orders o2 ON od2.orderNumber = o2.orderNumber WHERE YEAR(o2.orderDate) = 2004 );	classicmodels
SELECT c.customerNumber, c.customerName FROM customers c WHERE NOT EXISTS ( SELECT 1 FROM payments p WHERE p.customerNumber = c.customerNumber AND YEAR(p.paymentDate) = 2003 );	classicmodels
SELECT p.productName, o.orderDate, DAYNAME(o.orderDate) AS Day FROM products p JOIN orderdetails od ON p.productCode = od.productCode JOIN orders o ON od.orderNumber = o.orderNumber ORDER BY o.orderDate DESC;	classicmodels
SELECT DISTINCT(p.productName), o.orderDate FROM orders o JOIN orderdetails od ON o.orderNumber = od.orderNumber JOIN products p ON od.productCode = p.productCode WHERE p.productName = '1940 Ford Pickup Truck' ORDER BY o.orderDate DESC;	classicmodels
SELECT c.customerName, o.orderNumber, SUM(od.quantityOrdered * od.priceEach) AS value FROM customers c JOIN orders o ON c.customerNumber = o.customerNumber JOIN orderdetails od ON o.orderNumber = od.orderNumber GROUP BY c.customerName, o.orderNumber HAVING value > 25000 ORDER BY value DESC;	classicmodels
SELECT od.productCode FROM orderdetails od JOIN orders o ON od.orderNumber = o.orderNumber GROUP BY od.productCode HAVING COUNT(DISTINCT o.orderNumber) = (SELECT COUNT(DISTINCT orderNumber) FROM orders);	classicmodels
SELECT p.productName, p.MSRP, od.priceEach FROM products p JOIN orderdetails od ON p.productCode = od.productCode WHERE od.priceEach < (p.MSRP * 0.8) ORDER BY p.MSRP;	classicmodels
SELECT p.productName, 2*(p.buyPrice) AS twice_buy_price, od.priceEach FROM products p JOIN orderdetails od ON p.productcode = od.productcode WHERE od.priceEach > 2*(p.buyPrice);	classicmodels
SELECT p.productName, DAYNAME(o.orderDate) AS day_of_the_week, o.orderDate FROM products p JOIN orderdetails od ON p.productCode = od.productCode JOIN orders o ON od.orderNumber = o.orderNumber WHERE DAYNAME(o.orderDate) = 'Monday';	classicmodels
SELECT DISTINCT p.productName, p.quantityInStock, o.status FROM orderDetails od JOIN orders o ON od.orderNumber = o.orderNumber JOIN products p ON od.productCode = p.productCode WHERE o.status = 'On Hold' ORDER BY p.quantityInStock DESC;	classicmodels
SELECT c.customername, CONCAT(e.firstname, ' ', e.lastname) AS 'Account Representative' FROM customers c JOIN employees e ON c.salesrepemployeenumber = e.employeenumber;	classicmodels
SELECT SUM(p.amount) AS total_payments, c.customername FROM payments p JOIN customers c ON p.customernumber = c.customernumber WHERE c.customername = 'Atelier graphique';	classicmodels
SELECT SUM(amount) AS total_payments, paymentDate FROM payments GROUP BY paymentDate ORDER BY total_payments DESC;	classicmodels
SELECT * FROM products p WHERE NOT EXISTS ( SELECT * FROM orderdetails o WHERE p.productcode = o.productcode );	classicmodels
SELECT c.customerName, o.ordernumber, ROUND(SUM(od.quantityOrdered * od.priceEach), 2) AS amount_paid FROM customers c JOIN orders o ON c.customernumber = o.customernumber JOIN orderdetails od ON o.orderNumber = od.orderNumber GROUP BY o.ordernumber, c.customerName ORDER BY amount_paid DESC;	classicmodels
SELECT COUNT(o.ordernumber) AS 'orders', c.customerName FROM orders o JOIN customers c ON o.customernumber = c.customernumber WHERE c.customername = 'Herkku Gifts' GROUP BY c.customername;	classicmodels
SELECT CONCAT(e.firstname, ' ', e.lastname) AS employee_name FROM employees e WHERE e.officecode IN ( SELECT o.officecode FROM offices o WHERE o.city = 'Boston');	classicmodels
SELECT c.customerName, SUM(p.amount) AS high_payments FROM customers c JOIN payments p ON c.customernumber = p.customernumber WHERE p.amount > 100000 GROUP BY c.customername ORDER BY high_payments DESC;	classicmodels
SELECT SUM(p.amount) AS value, o.status FROM payments p JOIN orders o ON p.customernumber = o.customernumber WHERE o.status = 'On Hold';	classicmodels
SELECT COUNT(*) AS orders_on_hold, c.customername FROM orders o JOIN customers c ON o.customernumber = c.customernumber WHERE o.status = 'On Hold' GROUP BY c.customername;	classicmodels
SELECT * FROM products WHERE productName LIKE '%Ford%';	classicmodels
SELECT * FROM products WHERE productName LIKE '%ship';	classicmodels
SELECT COUNT(*) AS number_of_customers FROM customers WHERE country IN ('Denmark', 'Norway', 'Sweden');	classicmodels
SELECT * FROM products WHERE RIGHT(productCode, 4) BETWEEN 1000 AND 1499 ORDER BY RIGHT(productCode, 4);	classicmodels
SELECT * FROM customers WHERE customerName REGEXP '[0-9]';	classicmodels
SELECT * FROM employees WHERE firstName IN ('Dianne', 'Diane');	classicmodels
SELECT * FROM products WHERE productName REGEXP ('ship'|'boat');	classicmodels
SELECT * FROM products WHERE productCode LIKE 'S700%';	classicmodels
SELECT * FROM employees WHERE 'Larry' IN (lastName,firstName) OR 'Barry' IN (lastName,firstName);	classicmodels
SELECT * FROM employees WHERE CONCAT(firstname, ' ', lastname) REGEXP '[0-9%@]';	classicmodels
SELECT * FROM products WHERE productVendor LIKE '%Diecast';	classicmodels
SELECT * FROM offices ORDER BY country , state , city;	classicmodels
SELECT COUNT(DISTINCT employeeNumber) AS num_of_employees FROM employees;	classicmodels
SELECT SUM(amount) AS total_payments FROM payments;	classicmodels
SELECT productLine AS 'Cars' FROM productlines WHERE productLine LIKE '%Cars%';	classicmodels
SELECT SUM(amount) AS 'Amount for 28th oct 2004' FROM payments WHERE paymentDate = '2004-10-28';	classicmodels
SELECT * FROM payments WHERE amount > 100000 ORDER BY amount DESC;	classicmodels
SELECT productName, productLine FROM products ORDER BY productLine;	classicmodels
SELECT COUNT(productCode) AS num_of_products, productLine FROM products GROUP BY productLine ORDER BY num_of_products DESC;	classicmodels
SELECT MIN(amount) AS minimum_payment FROM payments;	classicmodels
SELECT amount FROM payments WHERE amount > 2 * ( SELECT AVG(amount) FROM payments );	classicmodels
SELECT AVG((MSRP - buyPrice) / MSRP) * 100 AS 'Average Percentage Markup' FROM products;	classicmodels
SELECT COUNT(DISTINCT productName) AS 'Distinct Product' FROM products;	classicmodels
SELECT customerName, city FROM customers WHERE salesRepEmployeeNumber IS NULL;	classicmodels
SELECT CONCAT(firstName, ' ', lastName) AS full_name FROM employees WHERE jobTitle LIKE '%VP%' OR jobTitle LIKE '%Manager%';	classicmodels
SELECT orderNumber, SUM(quantityOrdered * priceEach) AS 'Value' FROM orderdetails GROUP BY orderNumber HAVING Value > 5000 ORDER BY Value DESC;	classicmodels
SELECT customerNumber, customerName, ST_AsText(customerLocation) AS location, ST_Y(customerLocation) AS latitude, ST_X(customerLocation) AS longitude FROM customers WHERE ST_Y(customerLocation) < 0;	classicmodels
SELECT customerNumber, customerName, ST_AsText(customerLocation) AS location, ST_Y(customerLocation) AS latitude, ST_X(customerLocation) AS longitude FROM customers WHERE country = 'USA' AND ST_Y(customerLocation) < 40.7128 AND ST_X(customerLocation) < -74.0060;	classicmodels
SELECT c.customerNumber, c.customerName, ST_Distance(c.customerLocation, o.officeLocation) AS distance_to_tokyo FROM customers c JOIN offices o ON o.city = 'Tokyo' WHERE ST_Distance(c.customerLocation, o.officeLocation) <= ALL ( SELECT ST_Distance(c.customerLocation, o2.officeLocation) FROM offices o2 ) ORDER BY distance_to_tokyo ASC;	classicmodels
SELECT c.customerNumber, c.customerName, ST_Distance(c.customerLocation, o.officeLocation) AS distance_to_paris FROM customers c JOIN offices o ON o.city = 'Paris' WHERE c.country = 'France' AND ST_Distance(c.customerLocation, o.officeLocation) = ( SELECT MAX(ST_Distance(c2.customerLocation, o.officeLocation)) FROM customers c2 WHERE c2.country = 'France' ) ORDER BY distance_to_paris DESC;	classicmodels
SELECT customerNumber, customerName, ST_Y(customerLocation) AS latitude, ST_X(customerLocation) AS longitude FROM customers WHERE ST_Y(customerLocation) = ( SELECT MAX(ST_Y(customerLocation)) FROM customers);	classicmodels
SELECT (ACOS(SIN(ST_Y(paris.officeLocation) * PI() / 180) * SIN(ST_Y(boston.officeLocation) * PI() / 180) + COS(ST_Y(paris.officeLocation) * PI() / 180) * COS(ST_Y(boston.officeLocation) * PI() / 180) * COS((ST_X(paris.officeLocation) - ST_X(boston.officeLocation)) * PI() / 180)) * 180 / PI()) * 60 * 1.8532 AS distance_km FROM offices paris, offices boston WHERE paris.city = 'Paris' AND boston.city = 'Boston';	classicmodels
